<?php require_once __DIR__.'/../config/config.php'; require_once __DIR__.'/../config/auth.php'; require_login(); $page_title='Upload Dokumen'; $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $nama=trim($_POST['nama']??''); $kategori=trim($_POST['kategori']??''); $versi=trim($_POST['versi']??'1.0'); $tanggal_review=$_POST['tanggal_review']??null; if($nama==='') $error='Nama dokumen wajib diisi.'; elseif(empty($_FILES['file']['name'])) $error='File wajib dipilih.'; else { $allowed=['pdf','doc','docx','xls','xlsx','png','jpg','jpeg']; $ext=strtolower(pathinfo($_FILES['file']['name'],PATHINFO_EXTENSION)); if(!in_array($ext,$allowed,true)) $error='Jenis file tidak diizinkan.'; else { $dir=__DIR__.'/../uploads'; if(!is_dir($dir)) mkdir($dir,0775,true); $name=uniqid('doc_',true).'.'.$ext; move_uploaded_file($_FILES['file']['tmp_name'],$dir.'/'.$name); $st=$pdo->prepare('INSERT INTO dokumen(nama,kategori,versi,tanggal_review,filename,original_name,status,created_by) VALUES(?,?,?,?,?,?,?,?)'); $st->execute([$nama,$kategori,$versi,$tanggal_review,$name,$_FILES['file']['name'],'lengkap',$_SESSION['user']['id']]); header('Location:index.php'); exit; }}} require __DIR__.'/../partials/header.php'; ?><h2>Tambah Dokumen</h2><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif;?><div class="card shadow-sm border-0"><div class="card-body"><form method="post" enctype="multipart/form-data"><div class="mb-3"><label>Nama Dokumen</label><input class="form-control" name="nama" required></div><div class="row"><div class="col-md-6 mb-3"><label>Kategori</label><select class="form-select" name="kategori"><option>SOP</option><option>Kebijakan</option><option>Pedoman</option><option>SK</option><option>Laporan</option><option>Formulir</option><option>Bukti Implementasi</option></select></div><div class="col-md-3 mb-3"><label>Versi</label><input class="form-control" name="versi" value="1.0"></div><div class="col-md-3 mb-3"><label>Tanggal Review</label><input class="form-control" type="date" name="tanggal_review"></div></div><div class="mb-3"><label>File</label><input class="form-control" type="file" name="file" required></div><button class="btn btn-success">Simpan</button></form></div></div><?php require __DIR__.'/../partials/footer.php';